package org.myforeverpet.paradise;
public class PetStateTest {
 static void eq(boolean ok,String m){if(!ok)throw new AssertionError(m);}
 public static void main(String[] args){
  long t=1000000;PetState s=new PetState();eq(s.stage==0,"egg");s.changeField(1);s.hatch(t);s.advance(t+PetState.HOUR);eq(s.cells[1]==4,"field cells");eq(s.hunger==1,"baby hunger");eq(s.happy==8,"baby happiness");eq(s.inspectCell()&&s.stage==2,"kid");
  for(int i=0;i<4;i++)s.feed(2);eq(s.hunger==5,"feeding");int recycleWaste=s.waste;int coinsBeforeClean=s.coins;s.clean();eq(s.waste==0&&s.coins==coinsBeforeClean+2*recycleWaste,"clean and recycle payout");int cleanBalance=s.coins;s.clean();eq(s.coins==cleanBalance,"no duplicate recycle payout");
  s.advance(t+25*PetState.HOUR);eq(s.stage==3&&s.body==2,"young food branch");s.advance(t+49*PetState.HOUR);eq(s.stage==4,"adult");eq(s.sick,"illness");int misses=s.mistakes;s.treat();eq(s.sick&&s.germs==2,"one germ treated");s.treat();s.treat();eq(!s.sick&&s.mistakes==misses,"treat preserves care history");int beforeReward=s.coins;s.reward(5);eq(s.coins==beforeReward+25,"minigame reward");int generationBalance=s.coins;
  eq(PetState.decode(s.encode()).encode().equals(s.encode()),"save round trip");String before=s.encode();s.advance(t+48*PetState.HOUR);eq(before.equals(s.encode()),"backwards clock");
  PetState p=new PetState();p.hatch(t);p.advance(t+30*PetState.MIN);p.changeField(2);p.advance(t+60*PetState.MIN);eq(!p.inspectCell(),"matching field requirement");p.advance(t+90*PetState.MIN);eq(p.inspectCell(),"second field completed");
  eq(PlaydateRules.base(2,3)==3,"rank difference");eq(PlaydateRules.base(5,0)==4,"secret priority");eq(PlaydateRules.fight(2,9,5,5),"fight mixed conditions");eq(!PlaydateRules.fight(2,9,5,10),"no fight if one side well");eq(!PlaydateRules.canBreed(false,true,4,false,false),"adult gate");eq(!PlaydateRules.canBreed(true,true,4,true,false),"unbreedable gate");
  eq(!s.breed(3,2,1,t+49*PetState.HOUR),"friendship gate");s.playdate(3,5,10,true);s.playdate(3,5,10,true);eq(s.friendship==4,"friendship cap");eq(s.breed(3,2,1,t+49*PetState.HOUR)&&s.stage==0&&s.generation==2&&s.inheritedEyes==2&&s.coins==generationBalance,"offspring state and retained coins");eq(PetState.decode(s.encode()).generation==2,"generation persistence");s.hatch(t+49*PetState.HOUR);s.advance(t+50*PetState.HOUR);s.inspectCell();s.advance(t+98*PetState.HOUR);eq(s.eyes==2,"inherited eyes");
  s.coins=200;eq(s.buy(0)&&s.coins==160,"shop debit");eq(!s.buy(0)&&s.coins==160,"no duplicate debit");eq(s.useItem(0)&&s.equipped==1,"equip");eq(PetState.decode(s.encode()).equipped==1,"inventory persistence");s.waste=4;s.clean();eq(s.fuel>=4&&s.travel(),"recycle and travel");eq(s.species()>=0&&s.species()<12,"species bounds");
  eq(Economy.reward(0,1000,900)==100,"reward cap");eq(Economy.reward(1,20,30)==0,"minimum play");Arcade fly=new Arcade(Arcade.FLY,1);fly.input(0,0);for(int i=0;i<200&&!fly.over;i++)fly.step();eq(fly.over,"fly collision");Arcade jump=new Arcade(Arcade.JUMP,1);jump.input(80,145);for(int i=0;i<60;i++)jump.step();eq(jump.ticks>0,"jump physics");Arcade star=new Arcade(0,1);star.input(80,96);for(int i=0;i<90;i++)star.step();eq(star.claim()==2&&star.claim()==0,"single payout");s.hunger=4;s.coins=0;eq(!s.purchaseFood(0)&&s.purchaseFood(3)&&s.hunger==5,"free food safety net");
  PetState r=new PetState();r.hatch(t);r.stage=PetState.KID;r.last=t;r.energy=50;eq(r.rest(t),"rest starts");r.advance(t+30*PetState.MIN);eq(!r.sleeping()&&r.energy>50,"rest recovery");r.hunger=5;eq(r.expedition(0,r.last),"expedition");r.advance(r.last+10*PetState.MIN);eq(r.pendingCoins>0&&r.collectExpedition()&&!r.collectExpedition(),"exactly one expedition payout");eq(r.daily(r.last)&&!r.daily(r.last),"daily gift once");r.materials=2;r.hunger=2;eq(r.cook()&&r.hunger==4&&r.materials==0,"cooking");eq(r.bath(r.last),"bath");r.stage=PetState.ADULT;r.bond=30;r.training=10;r.crystals=3;eq(r.evolveSecret()&&r.species()>=12&&r.species()<24,"secret evolution");eq(PetState.decode(r.encode()).encode().equals(r.encode()),"new state round trip");String legacy=String.join(",",java.util.Arrays.copyOf(r.encode().split(","),34));eq(PetState.decode(legacy).coins==r.coins,"old state migration");Arcade find=new Arcade(Arcade.FIND,9);find.input(0,0);for(int i=0;i<80;i++)find.step();for(int i=0;i<8;i++){int j=find.hidden;find.input(20+(j%4)*40,51+(j/4)*38);}eq(find.over&&find.score==8&&find.claim()==80&&find.claim()==0,"find pet game and reward");
  System.out.println("PASS: egg, cell growth, food, cleaning, adulthood, illness, rewards, save, clock, field matching");
 }
}
